package uz.mirix.tracelens.internal;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.util.AntPathMatcher;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.servlet.HandlerMapping;import uz.mirix.tracelens.*;import java.io.IOException;import java.util.Map;
public final class TraceLensServletFilter extends OncePerRequestFilter {private final TraceLensProperties p;private final TraceLifecycle l;private final AntPathMatcher matcher=new AntPathMatcher();public TraceLensServletFilter(TraceLensProperties p,TraceLifecycle l){this.p=p;this.l=l;}protected boolean shouldNotFilter(HttpServletRequest r){String path=r.getRequestURI();return p.getWeb().getExclude().stream().anyMatch(x->matcher.match(x,path));}protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{if(!l.shouldTrace()){chain.doFilter(request,response);return;}TraceContext c=l.start(request.getMethod(),request.getRequestURI());TraceLensHttpServletResponseWrapper wrapped=new TraceLensHttpServletResponseWrapper(response);TraceContextHolder.bind(c);Throwable failure=null;try{chain.doFilter(request,wrapped);}catch(ServletException|IOException|RuntimeException|Error ex){failure=ex;throw ex;}finally{long ended=System.nanoTime();long first=wrapped.firstWriteNanos();if(first>0&&ended>=first)c.record(TraceCategory.SERIALIZATION,"serialization / response write",first,ended,Map.of());TraceReport report=c.finish(route(request),response.getStatus(),failure,ended);if(p.getServerTiming().isEnabled()&&!response.isCommitted())response.setHeader("Server-Timing",ServerTimingFormatter.format(report,p));l.publish(report);TraceContextHolder.clear();}}private static String route(HttpServletRequest r){Object pattern=r.getAttribute(HandlerMapping.BEST_MATCHING_PATTERN_ATTRIBUTE);return pattern==null?r.getRequestURI():pattern.toString();}}
